def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    rocking_chair_patches = image_patch.find("rocking chair")

    if not rocking_chair_patches:
        return image_patch

    rocking_chair = rocking_chair_patches[0]

    # Find all items that could potentially be described as "light brown"
    potential_items = []
    for item_name in ["chair", "furniture"]:
        items = image_patch.find(item_name)
        for item in items:
            if item.verify_property(item_name, "light brown"):
                potential_items.append((item, item.overlaps_with(*rocking_chair.get_coordinates())))

    # Sort potential items by their proximity to the rocking chair
    potential_items.sort(key=lambda x: abs(x[0].horizontal_center - rocking_chair.horizontal_center))

    # Return the closest item that overlaps with the rocking chair
    for item, overlaps in potential_items:
        if overlaps:
            return item

    # If no overlapping item is found, return the closest item
    return potential_items[0][0]

