    man_patches = image_patch.find("man")
    suit_patches = image_patch.find("suit")

    if not man_patches or not suit_patches:
        return image_patch

    man_suit_pairs = [(man, suit) for man in man_patches for suit in suit_patches if man.overlaps_with(suit.left, suit.lower, suit.right, suit.upper)]

